"use strict";
const bookCache={};
const bookRequests=new Map();
let readingState={progress:{},font:'normal',paper:'cream'};
try{const p=JSON.parse(localStorage.getItem('archaeo-reading-room')||'{}');if(p&&p.progress&&typeof p.progress==='object'&&!Array.isArray(p.progress)){for(const [k,v] of Object.entries(p.progress))if(Number.isSafeInteger(v)&&v>=0&&v<1000&&k!=='__proto__')readingState.progress[k]=v;}if(['small','normal','large'].includes(p.font))readingState.font=p.font;if(['cream','green','night'].includes(p.paper))readingState.paper=p.paper;}catch{}
function readingShelf(){return [{id:'letters',title:'江湖来信',author:'考古浏览器原创',label:'原创短篇 · 非历史连载',chapterCount:story.length,characters:story.reduce((n,c)=>n+c.text.join('').length,0)},...classicShelf];}
function saveReading(){try{localStorage.setItem('archaeo-reading-room',JSON.stringify(readingState));}catch{}}
function ensureBook(id){if(id==='letters'){if(!bookCache[id])bookCache[id]={...readingShelf()[0],chapters:story.map(c=>({title:c.title,paragraphs:c.text})),license:'本站原创短篇，非当年已发表作品。'};return Promise.resolve(bookCache[id]);}if(bookCache[id])return Promise.resolve(bookCache[id]);if(!classicShelf.some(b=>b.id===id))return Promise.reject(Error('unknown book'));if(!bookRequests.has(id))bookRequests.set(id,fetch(`books/${id}.json?v=0.4.0`).then(r=>{if(!r.ok)throw Error('book unavailable');return r.json();}).then(b=>{if(b.id!==id||!Array.isArray(b.chapters)||!b.chapters.every(c=>typeof c.title==='string'&&Array.isArray(c.paragraphs)&&c.paragraphs.every(t=>typeof t==='string')))throw Error('invalid book');bookCache[id]=b;return b;}).catch(e=>{bookRequests.delete(id);throw e;}));return bookRequests.get(id);}
function openBookshelf(){navigate({type:'bookshelf',name:'掌上书房',url:'archaeo://books'});}
function renderBookshelf(){return `<section class="book-room"><header><small>THE LITTLE READING ROOM / 掌上书房</small><h1>小小屏幕，装得下整个江湖。</h1><p>关掉灯，翻一页。那些在被窝里读小说的晚上，还记得吗？</p><nav><button data-action="home">时光首页</button><button data-phone-lab>到旧手机里读</button><button data-open-skins>换肤</button></nav></header><div class="bookshelf-grid">${readingShelf().map((b,i)=>`<article class="shelf-book"><button class="shelf-cover cover-${i}" data-open-book="${b.id}"><span>${escapeHTML(b.title)}</span><small>${escapeHTML(b.author)}</small></button><div><small>${escapeHTML(b.label)}</small><h2>${escapeHTML(b.title)}</h2><p>${b.chapterCount} 回已整理 · ${b.characters<1000?b.characters+' 字':(b.characters/10000).toFixed(1)+' 万字'}<br>${readingState.progress[b.id]!==undefined?`上次读到第 ${readingState.progress[b.id]+1} 回`:'还没有开始阅读'}</p><button data-open-book="${b.id}">${readingState.progress[b.id]!==undefined?'继续阅读':'开始阅读'} →</button><button data-book-contents="${b.id}">目录</button></div></article>`).join('')}</div><div class="reading-notes"><h2>年代书站，继续找找</h2><div>${[['起点中文网','www.qidian.com'],['红袖添香','www.hongxiu.com'],['榕树下','www.rongshuxia.com'],['晋江文学城','www.jjwxc.net']].map(([n,u])=>siteLink(n,u)).join('')}</div><p>本地提供公版经典与原创短篇；商业网络小说只提供历史站点入口。经典目前整理前五回，不冒充整本收录。</p></div></section>`;}
function openBook(id,chapter){const meta=readingShelf().find(b=>b.id===id);if(!meta)return;const c=Math.max(0,Math.min(meta.chapterCount-1,Number.isSafeInteger(Number(chapter))?Number(chapter):readingState.progress[id]||0));readingState.progress[id]=c;saveReading();navigate({type:'book',book:id,chapter:c,name:meta.title+' · 第'+(c+1)+'回',url:`archaeo://book/${id}/${c}`});const token=requestId;ensureBook(id).then(()=>{if(token===requestId&&current.type==='book')navigate(current,false);}).catch(()=>{if(token===requestId)navigate({...current,error:true},false);});}
function renderBook(page){const meta=readingShelf().find(b=>b.id===page.book);if(!meta)return '<p>未找到这本书。</p>';const book=bookCache[page.book],ch=book?.chapters[page.chapter];return `<article class="book-reader paper-${readingState.paper} text-${readingState.font}"><nav class="book-reader-toolbar"><button data-bookshelf>‹ 书架</button><button data-book-contents="${meta.id}">目录</button><button data-reader-font="small">小</button><button data-reader-font="normal">中</button><button data-reader-font="large">大</button><button data-reader-paper="${readingState.paper==='night'?'cream':'night'}">${readingState.paper==='night'?'日间':'夜读'}</button><button data-capture-view>保存这一页</button></nav><div class="book-paper"><header><small>${escapeHTML(meta.title)} / ${escapeHTML(meta.author)}</small><h1>${escapeHTML(ch?.title||'正在打开这一回…')}</h1><p>${escapeHTML(meta.label)} · 阅读进度保存在本机</p></header><div class="book-prose">${ch?ch.paragraphs.map(t=>`<p>${escapeHTML(t)}</p>`).join(''):`<p>${page.error?'暂时无法打开正文，请检查网络后重试。':'正在载入正文，只下载你打开的这本书。'}</p>${page.error?`<button data-open-book="${meta.id}" data-book-chapter="${page.chapter}">重新载入</button>`:''}`}</div><div class="book-pagination"><button data-open-book="${meta.id}" data-book-chapter="${page.chapter-1}" ${page.chapter===0?'disabled':''}>上一回</button><span>${page.chapter+1} / ${meta.chapterCount}</span><button data-open-book="${meta.id}" data-book-chapter="${page.chapter+1}" ${page.chapter>=meta.chapterCount-1?'disabled':''}>下一回</button></div><footer>${ch?.source?`<a href="${escapeHTML(ch.source)}" target="_blank" rel="noopener noreferrer">正文来源 · 维基文库固定版本</a> · <a href="${escapeHTML(ch.history)}" target="_blank" rel="noopener noreferrer">编校历史</a>`:'本站原创短篇'}<p>${escapeHTML(book?.license||'公版经典资料整理')}</p></footer></div></article>`;}
function bookContents(id){const meta=readingShelf().find(b=>b.id===id);if(!meta)return;dialog(meta.title+' · 目录',`<div class="book-chapter-list">${Array.from({length:meta.chapterCount},(_,i)=>`<button data-open-book="${id}" data-book-chapter="${i}">第 ${i+1} 回 ${readingState.progress[id]===i?'· 正在读':''}</button>`).join('')}</div><p class="scene-note">${meta.label}</p>`);}
function phoneBookMarkup(){const s=phoneState;if(!s.book)return `<div class="phone-wap-title">掌上书房</div>${readingShelf().map(b=>`<button class="phone-book-entry" data-phone-read="${b.id}"><b>${escapeHTML(b.title)}</b><small>${escapeHTML(b.label)} · ${b.chapterCount}回</small></button>`).join('')}<p class="phone-small-note">公版经典与本站原创短篇<br>打开后可滚动阅读，进度存本机。</p>`;const meta=readingShelf().find(b=>b.id===s.book),book=bookCache[s.book],ch=book?.chapters[s.chapter];if(!meta)return '';return `<div class="phone-paper"><button data-phone-bookshelf>‹ 书架</button><h2>${escapeHTML(meta.title)}</h2><b>${escapeHTML(ch?.title||'正在载入…')}</b>${ch?ch.paragraphs.map(t=>`<p>${escapeHTML(t)}</p>`).join(''):'<p>正在载入正文…</p>'}<div class="phone-book-pagination"><button data-phone-chapter="${s.chapter-1}" ${s.chapter===0?'disabled':''}>上一回</button><span>${s.chapter+1}/${meta.chapterCount}</span><button data-phone-chapter="${s.chapter+1}" ${s.chapter>=meta.chapterCount-1?'disabled':''}>下一回</button></div><small>${escapeHTML(meta.label)} · 来源详见浏览器书房</small></div>`;}
function phoneReadBook(id,chapter){const b=readingShelf().find(b=>b.id===id);if(!b)return;phoneState.book=id;phoneState.chapter=Math.max(0,Math.min(b.chapterCount-1,Number.isInteger(chapter)?chapter:readingState.progress[id]||0));phoneState.app='books';readingState.progress[id]=phoneState.chapter;saveReading();refreshPhone();ensureBook(id).then(()=>{if(current.type==='phone'&&phoneState.app==='books'&&phoneState.book===id)refreshPhone();}).catch(()=>toast('正文暂时未载入，可回书架后重试'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-bookshelf],[data-open-book],[data-book-contents],[data-reader-font],[data-reader-paper],[data-phone-read],[data-phone-chapter],[data-phone-bookshelf]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-bookshelf')){return openBookshelf();}if(b.dataset.openBook){$('#modal').close();return openBook(b.dataset.openBook,b.dataset.bookChapter);}if(b.dataset.bookContents)return bookContents(b.dataset.bookContents);if(b.dataset.readerFont&&['small','normal','large'].includes(b.dataset.readerFont)){readingState.font=b.dataset.readerFont;saveReading();navigate(current,false);}if(b.dataset.readerPaper&&['cream','green','night'].includes(b.dataset.readerPaper)){readingState.paper=b.dataset.readerPaper;saveReading();navigate(current,false);}if(b.dataset.phoneRead)phoneReadBook(b.dataset.phoneRead);if(b.dataset.phoneChapter!==undefined)phoneReadBook(phoneState.book,Number(b.dataset.phoneChapter));if(b.hasAttribute('data-phone-bookshelf')){phoneState.book=null;refreshPhone();}});
